      "exam_answer_type": "essay",
      "exam_wording": "《诗经》以四言为主，重章叠句造成回环复沓的音乐节奏，并通过换字推进情感；内容上紧贴现实、直面人生，形成“饥者歌其食，劳者歌其事”的现实主义传统。\n\n首先，从{{accent|句式章法}}来看，四言为主、二节拍鲜明；重章叠句便于反复咏唱，也能通过换字推动意义和情感层次。\n\n其次，从{{accent|现实主义内容}}来看，怨刺、徭役、婚恋和农事诗都从现实生活出发，表达真情实感，少有虚幻铺陈。\n\n最后，从{{accent|文学史影响}}来看，由此确立抒情诗传统、风雅精神和面向民间与现实的诗歌方向。\n\n例如，《芣苢》只换六个动词写采集过程，体现重章叠句的动态作用。\n\n从总分关系看，总体判断由句式章法、现实主义内容、文学史影响共同支撑：各分项从不同侧面展开，最后又回到同一中心结论，不能把其中任何一项孤立处理。\n\n综上，《诗经》的章法与现实主义传统所涉及的句式章法、现实主义内容、文学史影响应当按照“总分统摄”的关系统合起来；既落实具体事实和例证，也回扣中心判断，才能完整呈现这一考点的内在结构与意义。",
