      "title": "古今字与异体字的边界",
      "prompt": "如何区分古今字和异体字？",
      "summary": "{{accent|古今字是同一词在历史发展中先后使用不同字形}}，通常形成古字与今字的分工；异体字是同一字、同一词义的不同书写形体，时代先后和意义分工不是必要条件。",
      "outline_logic": {
        "type": "contrast",
        "description": "以{{accent|古今字、异体字、判断关键词}}为对照维度，先分别界定，再比较边界并形成判断。"
      },
      "outline": [
        {
          "heading": "古今字",
          "text": "古字和今字有先后关系，今字常承担古字原有的某个义项，形成分化和职能分工。"
        },
        {
          "heading": "异体字",
          "text": "同一字的不同形体在同一时期或不同地区并存，读音和意义基本相同，不以古今先后为核心。"
        },
        {
          "heading": "判断关键词",
          "text": "看到“分化、另造今字、古今职能”先考虑古今字；只见形体差异而无意义分工，优先考虑异体字。"
        }
      ],
      "examples": [
        "“莫—暮”等字组要结合词义分化和历史使用判断，不能只凭字形相近。"
      ],
      "hints": [
        {
          "level": 1,
          "kind": "structure",
          "text": "先问是否同一词。"
        },
        {
          "level": 2,
          "kind": "keywords",
          "text": "关键词：先后分工／同字异形。"
        },
        {
          "level": 3,
          "kind": "starter",
          "text": "没有历史证据时不要把理解性推测写成绝对结论。"
        }
      ],
      "exam_answer_type": "term",
      "exam_wording": "古今字是同一词在历史发展中先后使用不同字形，通常形成古字与今字的分工；异体字是同一字、同一词义的不同书写形体，时代先后和意义分工不是必要条件。\n\n首先，从{{accent|古今字}}来看，古字和今字有先后关系，今字常承担古字原有的某个义项，形成分化和职能分工。\n\n其次，从{{accent|异体字}}来看，同一字的不同形体在同一时期或不同地区并存，读音和意义基本相同。\n\n最后，从{{accent|判断关键词}}来看，看到“分化、另造今字、古今职能”先考虑古今字；只见形体差异而无意义分工。\n\n综上，古今字与异体字的边界的关键是以古今字、异体字、判断关键词为判断维度，在明确概念边界后依据具体材料作出结论。",
