      "exam_answer_type": "term",
      "exam_wording": "通假是本有本字而在特定语境中临时借用同音或音近字；假借则是词义本来存在但没有专用字形，依声借用现成字，属于造字和用字史上的更根本关系。\n\n首先，从{{accent|通假字}}来看，本来有本字，古文中因书写习惯或语境临时借用音同、音近字，通常受具体语境限制。\n\n其次，从{{accent|假借字}}来看，本无专用字形，依声托事借用已有字表示词义；同音假借不是“本无其义”。\n\n最后，从{{accent|考场流程}}来看，先问本来有没有本字，再看是否受语境限制；材料和教材例证优先。\n\n综上，通假字与假借字的区别的关键是以通假字、假借字、考场流程为判断维度，在明确概念边界后依据具体材料作出结论。",
