      "exam_answer_type": "essay",
      "exam_wording": "司马迁的修史动机由父亲临终嘱托和“润泽鸿业”的太史职责出发，经李陵之祸和宫刑的巨大屈辱，升华为以著书寄托个人不平、保存历史真实并完成精神自救的“发愤著书”。\n\n首先，从{{accent|起点：父亲嘱托}}来看，司马谈临终要求司马迁继承太史职责，不忘完成论著。\n\n其次，从{{accent|转折：李陵之祸}}来看，司马迁为李陵辩护获罪受宫刑，肉体和精神均遭受毁灭性打击。\n\n最后，从{{accent|升华：著书自救}}来看，受辱后把个人苦难融入历史书写，以前贤受困而著书自励，完成从颂赞盛世到保存真实、寄托不平的转变。\n\n例如，《报任安书》中的“每念斯耻”说明个人屈辱是动机转折。\n\n从形成关系看，起点：父亲嘱托与升华：著书自救不能被割裂：前者揭示现象或条件，后者说明作用机制及其结果，起点：父亲嘱托、转折：李陵之祸、升华：著书自救共同构成可追溯的因果链条。\n\n综上，司马迁“发愤著书”的写作动机所涉及的起点：父亲嘱托、转折：李陵之祸、升华：著书自救应当按照“因果贯通”的关系统合起来；既落实具体事实和例证，也回扣中心判断，才能完整呈现这一考点的内在结构与意义。",
