      "module": "古代文学",
      "topic_id": "topic_706_5161b119d38d",
      "order": 20,
      "title": "《史记》的人物刻画与实录精神",
      "prompt": "《史记》如何写出人物的复杂性？什么是实录精神？",
      "summary": "《{{accent|史记}}》以人物为历史线索，把小人物写进历史，结合个性与共性，并通过多维透视、旁见侧出和互见法呈现人物复杂性；实录精神则是实事求是、不虚美、不隐恶。",
      "outline_logic": {
        "type": "total_sub",
        "description": "先给出总判断，再从{{accent|人物中心、多维呈现、实录原则}}逐项展开，最后回到整体评价。"
      },
      "outline": [
        {
          "heading": "人物中心",
          "text": "纪传体以人物生平组织历史，刺客、游侠、商人等小人物也获得历史位置。"
        },
        {
          "heading": "多维呈现",
          "text": "通过个性与共性、正面与侧面、不同篇章的互见，写出人物矛盾而立体的性格。"
        },
        {
          "heading": "实录原则",
          "text": "班固所谓“其文直，其事核，不虚美，不隐恶”，要求史家面对事实而不粉饰。"
        }
      ],
      "examples": [
        "项羽等人物在不同篇章中的互见可显示其复杂性。"
      ],
      "hints": [
        {
          "level": 1,
          "kind": "structure",
          "text": "先答“写谁”，再答“怎么写”。"
        },
        {
          "level": 2,
          "kind": "keywords",
          "text": "关键词：小人物—多维透视—互见法。"
        },
        {
          "level": 3,
          "kind": "starter",
          "text": "最后用“不虚美，不隐恶”收束实录精神。"
        }
      ],
      "exam_answer_type": "essay",
      "exam_wording": "《史记》以人物为历史线索，把小人物写进历史，结合个性与共性，并通过多维透视、旁见侧出和互见法呈现人物复杂性；实录精神则是实事求是、不虚美、不隐恶。\n\n首先，从{{accent|人物中心}}来看，纪传体以人物生平组织历史，刺客、游侠、商人等小人物也获得历史位置。\n\n其次，从{{accent|多维呈现}}来看，通过个性与共性、正面与侧面、不同篇章的互见，写出人物矛盾而立体的性格。\n\n最后，从{{accent|实录原则}}来看，班固所谓“其文直，其事核，不虚美，不隐恶”，要求史家面对事实而不粉饰。\n\n例如，项羽等人物在不同篇章中的互见可显示其复杂性。\n\n从总分关系看，总体判断由人物中心、多维呈现、实录原则共同支撑：各分项从不同侧面展开，最后又回到同一中心结论，不能把其中任何一项孤立处理。\n\n综上，《史记》的人物刻画与实录精神所涉及的人物中心、多维呈现、实录原则应当按照“总分统摄”的关系统合起来；既落实具体事实和例证，也回扣中心判断，才能完整呈现这一考点的内在结构与意义。",
      "tags": [
        "史记",
        "人物塑造",
        "实录精神",
        "历史导入",
        "尚未评估"
      ],
