      "order": 10,
      "title": "六书的三家说与“四体二用”",
      "prompt": "六书理论如何从三家说落实到“四体二用”？",
      "summary": "六书是传统文字学分析汉字结构和使用的分类系统；后世把象形、指事、会意、形声视为造字之体，把转注、假借视为用字之法，形成“{{accent|四体二用}}”的核心区分。",
      "outline_logic": {
        "type": "total_sub",
        "description": "先给出总判断，再从{{accent|三家说、四体二用、答题边界}}逐项展开，最后回到整体评价。"
      },
      "outline": [
        {
          "heading": "三家说",
          "text": "班固、郑众、许慎等对六书名称和次序有不同说法，但许慎《说文解字》体系影响最大。"
        },
        {
          "heading": "四体二用",
          "text": "象形、指事、会意、形声重在构形，是造字之体；转注、假借重在使用，是用字之法。"
        },
        {
          "heading": "答题边界",
          "text": "六书不是六种完全并列的造字法，转注、假借是否属于造字要特别说明。"
        }
      ],
      "examples": [
        "四体二用是六书答题中最容易失分的理论分界。"
      ],
      "hints": [
        {
          "level": 1,
          "kind": "structure",
          "text": "先说六书是什么。"
        },
        {
          "level": 2,
          "kind": "keywords",
          "text": "关键词：前四书造字—后二书用字。"
        },
        {
          "level": 3,
          "kind": "starter",
          "text": "结尾强调“四体二用”是分析框架而非绝对历史定论。"
        }
      ],
      "exam_answer_type": "term",
      "exam_wording": "六书是传统文字学分析汉字结构和使用的分类系统；后世把象形、指事、会意、形声视为造字之体，把转注、假借视为用字之法，形成“四体二用”的核心区分。\n\n首先，从{{accent|三家说}}来看，班固、郑众、许慎等对六书名称和次序有不同说法，但许慎《说文解字》体系影响最大。\n\n其次，从{{accent|四体二用}}来看，象形、指事、会意、形声重在构形，是造字之体；转注、假借重在使用，是用字之法。\n\n最后，从{{accent|答题边界}}来看，六书不是六种完全并列的造字法，转注、假借是否属于造字要特别说明。\n\n综上，六书的三家说与“四体二用”的关键是以三家说、四体二用、答题边界为判断维度，在明确概念边界后依据具体材料作出结论。",
      "tags": [
        "六书",
        "四体二用",
        "文字学",
        "历史导入",
        "尚未评估"
      ],
