      "order": 10,
      "title": "俄国形式主义的文学性与陌生化",
      "prompt": "俄国形式主义如何回答“什么使文学成为文学”？",
      "summary": "{{accent|俄国形式主义把研究对象从作者生平和社会背景转向作品的文学性}}，认为陌生化通过打破自动化感知、延长感受过程，使语言和形式重新变得可感。",
      "outline_logic": {
        "type": "total_sub",
        "description": "先给出总判断，再从{{accent|文学性、陌生化、形式研究}}逐项展开，最后回到整体评价。"
      },
      "outline": [
        {
          "heading": "文学性",
          "text": "文学性是使作品成为文学的形式特征，不等同于题材或作者身份。"
        },
        {
          "heading": "陌生化",
          "text": "通过异常的语言、结构和视角打破习惯化感知，让读者重新看见对象。"
        },
        {
          "heading": "形式研究",
          "text": "形式不是装饰，而是作品产生审美效果和意义的机制，应结合文本具体分析。"
        }
      ],
      "examples": [
        "词性反常、异常比喻和叙述顺序变化都可能造成陌生化。"
      ],
      "hints": [
        {
          "level": 1,
          "kind": "structure",
          "text": "先定义文学性。"
        },
        {
          "level": 2,
          "kind": "keywords",
          "text": "关键词：形式特征—自动化—可感性。"
        },
        {
          "level": 3,
          "kind": "starter",
          "text": "结尾落到文本细部分析，而非只讲理论史。"
        }
      ],
      "exam_answer_type": "term",
      "exam_wording": "俄国形式主义把研究对象从作者生平和社会背景转向作品的文学性，认为陌生化通过打破自动化感知、延长感受过程，使语言和形式重新变得可感。\n\n首先，从{{accent|文学性}}来看，文学性是使作品成为文学的形式特征，不等同于题材或作者身份。\n\n其次，从{{accent|陌生化}}来看，通过异常的语言、结构和视角打破习惯化感知，让读者重新看见对象。\n\n最后，从{{accent|形式研究}}来看，形式不是装饰，而是作品产生审美效果和意义的机制，应结合文本具体分析。\n\n综上，俄国形式主义的文学性与陌生化的关键是以文学性、陌生化、形式研究为判断维度，在明确概念边界后依据具体材料作出结论。",
      "tags": [
        "形式主义",
        "文学性",
        "陌生化",
        "历史导入",
        "尚未评估"
      ],
