      "title": "《孔乙己》的小伙计与丁举人",
      "prompt": "小伙计和丁举人分别承担什么叙事与批判功能？",
      "summary": "小伙计以十二岁旁观者的视角讲述{{accent|孔乙己}}，使读者看到“旁观如何成为帮凶”；丁举人虽只被转述，却以权力者打断孔乙己双腿的暴力，显示等级秩序对弱者的直接摧毁。",
      "outline_logic": {
        "type": "total_sub",
        "description": "先给出总判断，再从{{accent|小伙计视角、丁举人暴力、读者位置}}逐项展开，最后回到整体评价。"
      },
      "outline": [
        {
          "heading": "小伙计视角",
          "text": "他不是孔乙己本人，也不是酒客，而是被环境训练成旁观者的孩子，叙述因此冷静又带有伦理不安。"
        },
        {
          "heading": "丁举人暴力",
          "text": "孔乙己偷书后被“打了大半夜，再打折了腿”，权力差异把惩罚变成身体摧毁。"
        },
        {
          "heading": "读者位置",
          "text": "读者既看到孔乙己的可笑，也被迫反思自己是否在重复酒客的观看。"
        }
      ],
      "examples": [
        "小伙计说“掌柜仍然同平常一样”，凸显日常秩序的冷漠。"
      ],
      "hints": [
        {
          "level": 1,
          "kind": "structure",
          "text": "先分别定位两个角色。"
        },
        {
          "level": 2,
          "kind": "keywords",
          "text": "关键词：旁观者—权力者—读者。"
        },
        {
          "level": 3,
          "kind": "starter",
          "text": "最后说明叙述视角如何把批判扩展到读者。"
        }
      ],
      "exam_answer_type": "essay",
      "exam_wording": "小伙计以十二岁旁观者的视角讲述孔乙己，使读者看到“旁观如何成为帮凶”；丁举人虽只被转述，却以权力者打断孔乙己双腿的暴力，显示等级秩序对弱者的直接摧毁。\n\n首先，从{{accent|小伙计视角}}来看，他不是孔乙己本人，也不是酒客，而是被环境训练成旁观者的孩子，叙述因此冷静又带有伦理不安。\n\n其次，从{{accent|丁举人暴力}}来看，孔乙己偷书后被“打了大半夜，再打折了腿”，权力差异把惩罚变成身体摧毁。\n\n最后，从{{accent|读者位置}}来看，读者既看到孔乙己的可笑，也被迫反思自己是否在重复酒客的观看。\n\n例如，小伙计说“掌柜仍然同平常一样”，凸显日常秩序的冷漠。\n\n从总分关系看，总体判断由小伙计视角、丁举人暴力、读者位置共同支撑：各分项从不同侧面展开，最后又回到同一中心结论，不能把其中任何一项孤立处理。\n\n综上，《孔乙己》的小伙计与丁举人所涉及的小伙计视角、丁举人暴力、读者位置应当按照“总分统摄”的关系统合起来；既落实具体事实和例证，也回扣中心判断，才能完整呈现这一考点的内在结构与意义。",
      "tags": [
        "孔乙己",
        "小伙计",
        "丁举人",
        "历史导入",
        "尚未评估"
      ],
