      "order": 10,
      "title": "陌生化的定义与作用机制",
      "prompt": "什么是陌生化？它怎样恢复审美感受？",
      "summary": "{{accent|陌生化是把习以为常的对象用不习惯的方式呈现}}，打破自动化感知，延长读者的感受和辨认过程，使原本被忽略的对象重新变得可感。",
      "outline_logic": {
        "type": "causal",
        "description": "由{{accent|自动化}}出发，依次推进到形式打破、审美效果，说明形成条件、作用机制及结果。"
      },
      "outline": [
        {
          "heading": "自动化",
          "text": "日常重复使感知变得省力，熟悉对象会被快速识别而不再真正被看见。"
        },
        {
          "heading": "形式打破",
          "text": "异常词性、句式、比喻、视角或结构让读者停下来重新加工。"
        },
        {
          "heading": "审美效果",
          "text": "感受过程被延长，读者不仅知道对象是什么，还重新体验对象如何呈现。"
        }
      ],
      "examples": [
        "“把熟悉的东西说得不熟悉”是最简短的记忆入口。"
      ],
      "hints": [
        {
          "level": 1,
          "kind": "structure",
          "text": "先答自动化。"
        },
        {
          "level": 2,
          "kind": "keywords",
          "text": "关键词：打破—停顿—重新感受。"
        },
        {
          "level": 3,
          "kind": "starter",
          "text": "不要把陌生化只理解为生造奇怪词语。"
        }
      ],
      "exam_answer_type": "term",
      "exam_wording": "陌生化是把习以为常的对象用不习惯的方式呈现，打破自动化感知，延长读者的感受和辨认过程，使原本被忽略的对象重新变得可感。\n\n首先，从{{accent|自动化}}来看，日常重复使感知变得省力，熟悉对象会被快速识别而不再真正被看见。\n\n其次，从{{accent|形式打破}}来看，异常词性、句式、比喻、视角或结构让读者停下来重新加工。\n\n最后，从{{accent|审美效果}}来看，感受过程被延长，读者不仅知道对象是什么，还重新体验对象如何呈现。\n\n综上，陌生化的定义与作用机制的关键是以自动化、形式打破、审美效果为判断维度，在明确概念边界后依据具体材料作出结论。",
      "tags": [
        "陌生化",
        "形式主义",
        "评论写作",
        "历史导入",
        "尚未评估"
      ],
