      "exam_answer_type": "quick",
      "exam_wording": "可按“发现异常—描述形式—解释感受—联系主题”的链条操作：先找到让直觉停顿的细部，再说明语言或结构哪里不同，最后解释这种形式如何改变读者感受并服务主题。\n\n首先，{{accent|发现异常}}：定位词性、句式、语域或意象反复等异常细节。\n\n其次，{{accent|解释机制}}：说明形式怎样打破自动化并改变阅读感受。\n\n最后，{{accent|回到主题}}：把审美效果与人物、叙事或主题意义连接起来。",
