      "topic_id": "topic_807_e1a03dd04f7a",
      "order": 10,
      "title": "《药》的三重“吃人”结构",
      "prompt": "《药》如何从字面、隐喻和象征三个层面写“吃人”？",
      "summary": "{{accent|《药》先写人血馒头的字面之吃}}，再写群众以愚昧和冷漠消耗夏瑜的隐喻之吃，最后通过华、夏两姓和革命者与普通人的隔绝，把封建社会的生命吞噬提升为象征结构。",
      "outline_logic": {
        "type": "parallel",
        "description": "围绕总问题，从{{accent|字面之吃、隐喻之吃、象征之吃}}等并列维度展开，最后归纳共同意义。"
      },
      "outline": [
        {
          "heading": "字面之吃",
          "text": "华老栓买夏瑜鲜血浸透的人血馒头给华小栓治病，形成残酷的事件链。"
        },
        {
          "heading": "隐喻之吃",
          "text": "群众围观、议论和消费革命者的死亡，显示麻木的社会如何吞噬个体。"
        },
        {
          "heading": "象征之吃",
          "text": "“华”与“夏”分别牵连民族与革命的寓意，革命者和民众彼此隔绝，形成双重悲剧。"
        }
      ],
      "examples": [
        "买药、吃药、谈药、坟场四节逐步扩大“吃”的含义。"
      ],
      "hints": [
        {
          "level": 1,
          "kind": "structure",
          "text": "先列三层。"
        },
        {
          "level": 2,
          "kind": "keywords",
          "text": "关键词：血馒头—看客—革命隔绝。"
        },
        {
          "level": 3,
          "kind": "starter",
          "text": "结尾说明问题不只是一个恶人，而是社会结构。"
        }
      ],
      "exam_answer_type": "essay",
      "exam_wording": "《药》先写人血馒头的字面之吃，再写群众以愚昧和冷漠消耗夏瑜的隐喻之吃，最后通过华、夏两姓和革命者与普通人的隔绝，把封建社会的生命吞噬提升为象征结构。\n\n首先，从{{accent|字面之吃}}来看，华老栓买夏瑜鲜血浸透的人血馒头给华小栓治病，形成残酷的事件链。\n\n其次，从{{accent|隐喻之吃}}来看，群众围观、议论和消费革命者的死亡，显示麻木的社会如何吞噬个体。\n\n最后，从{{accent|象征之吃}}来看，“华”与“夏”分别牵连民族与革命的寓意，革命者和民众彼此隔绝，形成双重悲剧。\n\n例如，买药、吃药、谈药、坟场四节逐步扩大“吃”的含义。\n\n从整体关系看，字面之吃、隐喻之吃、象征之吃是围绕同一问题展开的并列维度，各自承担不同的解释任务，不能相互替代；把这些维度合并起来，才能形成完整判断。\n\n综上，《药》的三重“吃人”结构所涉及的字面之吃、隐喻之吃、象征之吃应当按照“并列互补”的关系统合起来；既落实具体事实和例证，也回扣中心判断，才能完整呈现这一考点的内在结构与意义。",
      "tags": [
        "药",
        "吃人结构",
        "鲁迅",
        "历史导入",
        "尚未评估"
      ],
