      "title": "马克思主义的三大组成部分",
      "prompt": "马克思主义由哪些部分构成？三者如何理解？",
      "summary": "{{accent|马克思主义通常由}}马克思主义哲学、马克思主义政治经济学和科学社会主义三大部分构成。三者分别提供世界观和方法论、资本主义经济结构分析以及社会主义由理论走向现实的科学依据。",
      "outline_logic": {
        "type": "parallel",
        "description": "围绕总问题，从{{accent|哲学、政治经济学、科学社会主义}}等并列维度展开，最后归纳共同意义。"
      },
      "outline": [
        {
          "heading": "哲学",
          "text": "回答世界是什么、怎样认识和改造世界，提供总体的世界观和方法论基础。"
        },
        {
          "heading": "政治经济学",
          "text": "分析商品、资本和资本主义生产关系，揭示资本运行和剥削机制。"
        },
        {
          "heading": "科学社会主义",
          "text": "说明资本主义向社会主义发展的历史条件、现实道路和最终方向。"
        }
      ],
      "examples": [
        "记忆口诀“德资共反”对应导论中的经典著作线索，不等同于三大组成部分。"
      ],
      "hints": [
        {
          "level": 1,
          "kind": "structure",
          "text": "先列三部分。"
        },
        {
          "level": 2,
          "kind": "keywords",
          "text": "关键词：世界观—经济结构—历史方向。"
        },
        {
          "level": 3,
          "kind": "starter",
          "text": "最后写三者相互联系而不是三个孤立学科。"
        }
      ],
      "exam_answer_type": "short_answer",
      "exam_wording": "马克思主义通常由马克思主义哲学、马克思主义政治经济学和科学社会主义三大部分构成。三者分别提供世界观和方法论、资本主义经济结构分析以及社会主义由理论走向现实的科学依据。\n\n首先，从{{accent|哲学}}来看，回答世界是什么、怎样认识和改造世界，提供总体的世界观和方法论基础。\n\n其次，从{{accent|政治经济学}}来看，分析商品、资本和资本主义生产关系，揭示资本运行和剥削机制。\n\n最后，从{{accent|科学社会主义}}来看，说明资本主义向社会主义发展的历史条件、现实道路和最终方向。\n\n从整体关系看，哲学、政治经济学、科学社会主义是围绕同一问题展开的并列维度，各自承担不同的解释任务，不能相互替代；把这些维度合并起来，才能形成完整判断。\n\n综上，马克思主义的三大组成部分所涉及的哲学、政治经济学、科学社会主义应当按照“并列互补”的关系统合起来；既落实具体事实和例证，也回扣中心判断，才能完整呈现这一考点的内在结构与意义。",
