      "exam_answer_type": "short_answer",
      "exam_wording": "基本立场回答站在谁的立场上，核心是人民立场；基本观点回答认识什么，涉及自然、社会和思维发展的规律；基本方法回答怎样分析和实践，强调实事求是、矛盾分析和实践检验。\n\n首先，从{{accent|基本立场}}来看，站在无产阶级和最广大人民立场上，追求人的解放与全面发展。\n\n其次，从{{accent|基本观点}}来看，关于自然、社会和思维运动规律的理论认识，如生产力与生产关系等。\n\n最后，从{{accent|基本方法}}来看，以实践为基础，实事求是、具体问题具体分析，并在实践中检验和发展认识。\n\n从整体关系看，基本立场、基本观点、基本方法是围绕同一问题展开的并列维度，各自承担不同的解释任务，不能相互替代；把这些维度合并起来，才能形成完整判断。\n\n综上，马克思主义的基本立场、观点和方法所涉及的基本立场、基本观点、基本方法应当按照“并列互补”的关系统合起来；既落实具体事实和例证，也回扣中心判断，才能完整呈现这一考点的内在结构与意义。",
