      "subject": "politics",
      "module": "马原",
      "topic_id": "topic_politics_ce5a75105850",
      "order": 20,
      "title": "旧唯物主义的“半截子”局限",
      "prompt": "为什么说旧唯物主义是“半截子唯物主义”？马克思主义哲学克服了什么？",
      "summary": "{{accent|旧唯物主义在自然观上坚持物质第一性}}，却在社会历史领域把历史归因于思想、英雄或偶然意志，因而没有把唯物主义贯彻到底；马克思主义以实践为基础创立唯物史观，并把唯物主义和辩证法统一起来。",
      "outline_logic": {
        "type": "total_sub",
        "description": "先给出总判断，再从{{accent|局限、唯物史观、辩证统一}}逐项展开，最后回到整体评价。"
      },
      "outline": [
        {
          "heading": "局限",
          "text": "自然观唯物、历史观唯心，只说明自然物质性，不能说明社会历史的物质基础和发展规律。"
        },
        {
          "heading": "唯物史观",
          "text": "把唯物主义贯彻到社会历史领域，说明生产实践和社会关系对历史发展的基础作用。"
        },
        {
          "heading": "辩证统一",
          "text": "马克思主义还把唯物主义与辩证法有机统一，克服旧唯物主义形而上学的机械性。"
        }
      ],
      "examples": [
        "“物质决定意识”不能自动推出对社会历史的正确解释，关键在是否贯彻到历史观。"
      ],
      "hints": [
        {
          "level": 1,
          "kind": "structure",
          "text": "先解释半截子。"
        },
        {
          "level": 2,
          "kind": "keywords",
          "text": "关键词：自然观唯物／历史观唯心。"
        },
        {
          "level": 3,
          "kind": "starter",
          "text": "最后答两大贡献。"
        }
      ],
      "exam_answer_type": "short_answer",
      "exam_wording": "旧唯物主义在自然观上坚持物质第一性，却在社会历史领域把历史归因于思想、英雄或偶然意志，因而没有把唯物主义贯彻到底；马克思主义以实践为基础创立唯物史观，并把唯物主义和辩证法统一起来。\n\n首先，从{{accent|局限}}来看，自然观唯物、历史观唯心，只说明自然物质性，不能说明社会历史的物质基础和发展规律。\n\n其次，从{{accent|唯物史观}}来看，把唯物主义贯彻到社会历史领域，说明生产实践和社会关系对历史发展的基础作用。\n\n最后，从{{accent|辩证统一}}来看，马克思主义还把唯物主义与辩证法有机统一，克服旧唯物主义形而上学的机械性。\n\n从总分关系看，总体判断由局限、唯物史观、辩证统一共同支撑：各分项从不同侧面展开，最后又回到同一中心结论，不能把其中任何一项孤立处理。\n\n综上，旧唯物主义的“半截子”局限所涉及的局限、唯物史观、辩证统一应当按照“总分统摄”的关系统合起来；既落实具体事实和例证，也回扣中心判断，才能完整呈现这一考点的内在结构与意义。",
      "tags": [
        "政治",
        "旧唯物主义",
        "唯物史观",
        "历史导入",
        "尚未评估"
      ],
