      "exam_answer_type": "quick",
      "exam_wording": "意识不是独立物质，但意识活动可以变化、发展和转化；这种变化不能脱离人脑这一特殊物质及社会实践。\n\n首先，{{accent|核心区分}}：运动是物质的根本属性，不存在脱离物质的运动；意识不是物质本身，而是人脑的机能和属性。\n\n最后，{{accent|正确表述}}：意识活动可以发生变化并反作用于物质，但必须依靠人脑、语言和社会实践等物质基础。",
